<script setup lang="ts">import{onMounted,ref}from'vue';import PageHeader from'../../components/PageHeader.vue';import{client,errorMessage,requireData}from'../../../shared/api/client';import type{components}from'../../../shared/api/schema.gen';const value=ref<components['schemas']['AISettings']>();const error=ref('');const saved=ref(false);onMounted(async()=>{try{value.value=requireData(await client.GET('/api/admin/settings/ai'))}catch(cause){error.value=errorMessage(cause)}});async function save(){if(!value.value)return;try{requireData(await client.PUT('/api/admin/settings/ai',{body:value.value}));saved.value=true}catch(cause){error.value=errorMessage(cause)}}async function rebuild(){if(!confirm('投递全量重建索引任务？这会产生嵌入费用。'))return;try{requireData(await client.POST('/api/admin/jobs/reindex'));saved.value=true}catch(cause){error.value=errorMessage(cause)}}</script>
<template><PageHeader title="AI 设置与启用条件" description="只有快速、精确和嵌入能力完整时才能启用。"/><p v-if="error" class="text-danger">{{ error }}</p><form v-if="value" class="grid max-w-xl gap-4" @submit.prevent="save"><label class="flex gap-2"><input v-model="value.enabled" type="checkbox">启用公开 AI 问答</label><label class="flex gap-2"><input v-model="value.exactCache" type="checkbox">精确缓存</label><label class="flex gap-2"><input v-model="value.semanticCache" type="checkbox">语义缓存</label><label>问题最大长度<input v-model.number="value.maxQuestionLength" type="number" class="nw-input"></label><label>最大对话轮数<input v-model.number="value.maxTurns" type="number" class="nw-input"></label><label>最大输出 token<input v-model.number="value.maxOutputTokens" type="number" class="nw-input"></label><label>每日花费上限<input v-model.number="value.dailySpendLimit" type="number" min="0" step="0.01" class="nw-input"></label><button class="nw-button">保存 AI 设置</button><button type="button" class="text-danger" @click="rebuild">全量重建索引</button><p v-if="saved">已保存或投递。</p></form></template>
